def can_traverse_all_pairs(nums):
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i, v in enumerate(nums):
        p = 2
        while p * p <= v:
            if v % p == 0:
                parent[find(("p", p))] = find(i)
                while v % p == 0:
                    v //= p
            p += 1
        if v > 1:
            parent[find(("p", v))] = find(i)
    return len({find(i) for i in range(n)}) == 1

def can_traverse_all_pairs(nums):
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False
    M = max(nums)
    spf = list(range(M + 1))                     # smallest prime factor
    for p in range(2, int(M ** 0.5) + 1):
        if spf[p] == p:
            for q in range(p * p, M + 1, p):
                if spf[q] == q:
                    spf[q] = p
    parent = list(range(n + M + 1))              # 0..n-1 indices, n+p primes

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i, v in enumerate(nums):
        while v > 1:
            p = spf[v]
            parent[find(n + p)] = find(i)
            while v % p == 0:
                v //= p
    root = find(0)
    return all(find(i) == root for i in range(n))
